schemaIntrospection.query:
{
    queryRoot: __type(name: "DotaQuery") {
      name fields { name description type { kind name ofType { kind name ofType { kind name } } } }
    }
    heroStats: __type(name: "HeroStatsQuery") {
      name fields {
        name description type { kind name ofType { kind name ofType { kind name } } }
        args { name description type { kind name ofType { kind name ofType { kind name } } } }
      }
    }
    dryad: __type(name: "HeroDryadType") {
      name fields { name description type { kind name ofType { kind name ofType { kind name } } } }
    }
    matchup: __type(name: "HeroStatsHeroDryadType") {
      name fields { name description type { kind name ofType { kind name ofType { kind name } } } }
    }
  }

